/* Origins 27 · 02-sprites.js
   Sprites pixel art (images PNG en base64) et fonctions pour les afficher.
   Chargé dans l’ordre par index.html ; tous les fichiers partagent les mêmes variables globales. */
"use strict";
/* Sprites pixel art (planches d’illustration du créateur) : [largeur, hauteur, PNG base64] */
const SPR={"r_atp":[16,16,""],"r_prot":[16,16,""],"r_lip":[16,23,""],"r_nuc":[16,16,""],"r_ess":[16,20,""],"o_noyau":[36,37,""],"o_mito":[24,25,""],"o_chloro":[24,23,""],"o_ribo":[24,27,""],"o_memb":[24,23,""],"o_vac":[24,24,""],"o_flag":[24,25,""],"o_cyto":[24,24,""],"o_golgi":[24,25,""],"o_photo":[24,44,""],"m_gis":[14,8,""],"c_proc":[14,12,""],"c_euc":[16,15,""],"c_colo":[20,17,""],"c_pluri":[22,21,""],"u_coll":[16,13,""],"u_phago":[16,11,""],"w_tox":[12,13,""],"w_pha":[12,10,""],"w_enz":[12,11,""],"w_har":[12,10,""],"g_tox":[24,31,""],"g_har":[24,25,""],"g_enz":[24,18,""],"g_par":[24,23,""],"g_pha":[24,25,""],"g_unk2":[24,24,""],"g_emerg":[24,22,""],"t_land":[72,39,""],"d_trex":[72,95,""],"d_ptero":[76,36,""],"d_brachio":[72,96,""],"d_raptor":[74,64,""],"d_trice":[78,59,""],"d_anky":[72,69,""],"d_stego":[70,63,""],"d_para":[74,62,""],"d_archeo":[60,49,""],"d_diplo":[80,78,""]};
const SPRI={};
function sprURL(k){return "data:image/png;base64,"+SPR[k][2];}
(function(){for(const k in SPR){const im=new Image();im.onload=()=>{try{dirty=true;}catch(e){/* image arrivée avant le chargement de 06-etat.js : rien à redessiner encore */}};im.src=sprURL(k);SPRI[k]=im;}})();
function sprImg(k,scale,cls,alt){const sp=SPR[k];if(!sp)return "";const dpr=window.devicePixelRatio||1,u=Math.max(1,Math.round((scale||1)*dpr));return '<img class="spr'+(cls?" "+cls:"")+'" src="'+sprURL(k)+'" width="'+sp[0]+'" height="'+sp[1]+'" style="width:'+(sp[0]*u/dpr)+'px;height:'+(sp[1]*u/dpr)+'px" alt="'+(alt||"")+'"'+(alt?"":' aria-hidden="true"')+'>';}
function sprSVG(k,cx,cy,unit,snap){const sp=SPR[k];if(!sp)return "";const w=sp[0]*unit,h=sp[1]*unit;let x=cx-w/2,y=cy-h/2;if(snap){x=Math.round((x-snap)/unit)*unit+snap;y=Math.round((y-snap)/unit)*unit+snap;}return '<image href="'+sprURL(k)+'" x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" preserveAspectRatio="none" style="image-rendering:pixelated"/>';}
function sprDraw(k,cx,cy,al){const im=SPRI[k];if(!im||!im.complete||!im.naturalWidth)return false;ctx.globalAlpha=al==null?1:al;ctx.drawImage(im,Math.round(cx-im.naturalWidth/2),Math.round(cy-im.naturalHeight/2));ctx.globalAlpha=1;return true;}
